-- Daily procedural missions: no money, no changes to security pay or shift settlement.
BEGIN;
CREATE TABLE IF NOT EXISTS public.job_mission_scripts (
 id text PRIMARY KEY, job_key text NOT NULL, title text NOT NULL,
 steps jsonb NOT NULL CHECK(jsonb_typeof(steps)='array' AND jsonb_array_length(steps)>=3)
);
CREATE TABLE IF NOT EXISTS public.job_mission_runs (
 character_id uuid NOT NULL REFERENCES public.characters(id) ON DELETE CASCADE,
 game_day date NOT NULL, script_id text NOT NULL REFERENCES public.job_mission_scripts(id),
 activity_id uuid NOT NULL REFERENCES public.activities(id), city_id uuid REFERENCES public.cities(id),
 answers integer[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','expired','success','failure')),
 reputation_delta integer, energy_cost integer, PRIMARY KEY(character_id,game_day)
);
CREATE TABLE IF NOT EXISTS public.job_mission_progress (
 character_id uuid NOT NULL REFERENCES public.characters(id) ON DELETE CASCADE,
 job_key text NOT NULL, successes integer NOT NULL DEFAULT 0 CHECK(successes>=0),
 milestone integer GENERATED ALWAYS AS (CASE WHEN successes>=50 THEN 3 WHEN successes>=25 THEN 2 WHEN successes>=10 THEN 1 ELSE 0 END) STORED,
 PRIMARY KEY(character_id,job_key)
);
ALTER TABLE public.job_mission_scripts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.job_mission_runs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.job_mission_progress ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS job_mission_runs_owner ON public.job_mission_runs;
CREATE POLICY job_mission_runs_owner ON public.job_mission_runs FOR SELECT TO authenticated USING(character_id=public.social_actor());
DROP POLICY IF EXISTS job_mission_progress_owner ON public.job_mission_progress;
CREATE POLICY job_mission_progress_owner ON public.job_mission_progress FOR SELECT TO authenticated USING(character_id=public.social_actor());
-- Scripts are private: scoring weights must not be exposed by direct SELECT.
REVOKE ALL ON public.job_mission_scripts,public.job_mission_runs,public.job_mission_progress FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.job_mission_runs,public.job_mission_progress TO authenticated;
GRANT ALL ON public.job_mission_scripts,public.job_mission_runs,public.job_mission_progress TO service_role;
ON CONFLICT(id) DO UPDATE SET job_key=excluded.job_key,title=excluded.title,steps=excluded.steps;
CREATE OR REPLACE FUNCTION public.job_mission_state() RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE cid uuid:=public.social_actor(); t timestamptz:=public.game_now(); d date; a public.activities; k text; s public.job_mission_scripts; r public.job_mission_runs; step jsonb;
BEGIN
 PERFORM 1 FROM public.characters WHERE id=cid FOR UPDATE;
 d:=(t AT TIME ZONE 'UTC')::date;
 UPDATE public.job_mission_runs SET status='expired' WHERE character_id=cid AND status='active' AND game_day<d;
 SELECT * INTO r FROM public.job_mission_runs WHERE character_id=cid AND game_day=d;
 IF NOT FOUND THEN
  -- A worked day starts with an actual running/completed agenda activity, never a planned shift.
  SELECT * INTO a FROM public.activities WHERE character_id=cid AND type IN ('work','security_shift')
   AND status IN ('running','completed') AND start_time<=t
   AND (start_time AT TIME ZONE 'UTC')::date=d ORDER BY start_time,id LIMIT 1;
  IF a.id IS NOT NULL THEN
   IF a.type='work' THEN
    SELECT j.title INTO k FROM public.employments e JOIN public.jobs j ON j.id=e.job_id WHERE e.character_id=cid;
   ELSE
    SELECT service INTO k FROM public.security_shifts WHERE character_id=cid AND 'security:'||request_id=a.source_key LIMIT 1;
   END IF;
   SELECT * INTO s FROM public.job_mission_scripts WHERE job_key=k
    ORDER BY hashtext(cid::text||d::text||id)::bigint,id LIMIT 1;
   IF s.id IS NOT NULL THEN
     SELECT cid,d,s.id,a.id,city_id FROM public.characters WHERE id=cid ON CONFLICT DO NOTHING;
   END IF;
  END IF;
  SELECT * INTO r FROM public.job_mission_runs WHERE character_id=cid AND game_day=d;
 END IF;
 IF r.script_id IS NULL THEN RETURN jsonb_build_object('mission',NULL); END IF;
 SELECT * INTO s FROM public.job_mission_scripts WHERE id=r.script_id;
 step:=s.steps->cardinality(r.answers);
 RETURN jsonb_build_object('mission',jsonb_build_object('day',r.game_day,'title',s.title,'job',s.job_key,'city_id',r.city_id,
  'status',r.status,'step_index',cardinality(r.answers),'step_count',jsonb_array_length(s.steps),
  'step',CASE WHEN r.status='active' THEN jsonb_build_object('text',step->>'text','choices',
   (SELECT jsonb_agg(jsonb_build_object('label',x->>'label') ORDER BY n) FROM jsonb_array_elements(step->'choices') WITH ORDINALITY c(x,n))) ELSE NULL END,
  'reputation_delta',r.reputation_delta,'energy_cost',r.energy_cost),
  'progress',COALESCE((SELECT jsonb_build_object('successes',successes,'milestone',milestone) FROM public.job_mission_progress WHERE character_id=cid AND job_key=s.job_key),jsonb_build_object('successes',0,'milestone',0)));
END $$;
CREATE OR REPLACE FUNCTION public.job_mission_choose(_day date,_step integer,_choice integer) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE cid uuid:=public.social_actor(); r public.job_mission_runs; s public.job_mission_scripts; picked integer[]; score integer:=0; i integer; roll integer; rep integer; cost integer; ok boolean;
BEGIN
 PERFORM 1 FROM public.characters WHERE id=cid FOR UPDATE;
 PERFORM public.job_mission_state();
 SELECT * INTO r FROM public.job_mission_runs WHERE character_id=cid AND game_day=_day FOR UPDATE;
 IF r.script_id IS NULL OR r.status<>'active' THEN RETURN public.job_mission_state(); END IF;
 IF _step<cardinality(r.answers) THEN RETURN public.job_mission_state(); END IF;
 IF _step IS DISTINCT FROM cardinality(r.answers) THEN RAISE EXCEPTION 'Étape inattendue'; END IF;
 SELECT * INTO s FROM public.job_mission_scripts WHERE id=r.script_id;
 IF _choice IS NULL OR _choice<0 OR _choice>=jsonb_array_length(s.steps->_step->'choices') THEN RAISE EXCEPTION 'Choix invalide'; END IF;
 picked:=array_append(r.answers,_choice);
 UPDATE public.job_mission_runs SET answers=picked WHERE character_id=cid AND game_day=_day;
 IF cardinality(picked)=jsonb_array_length(s.steps) THEN
  FOR i IN 1..cardinality(picked) LOOP
   score:=score+(s.steps->(i-1)->'choices'->picked[i]->>'weight')::integer;
  END LOOP;
  roll:=((hashtext(cid::text||_day::text||s.id||picked::text)::bigint & 2147483647)%100)::integer;
  ok:=roll<LEAST(90,45+score*5);
  rep:=CASE WHEN ok THEN 1+roll%3 ELSE -1-roll%2 END;
  cost:=5+roll%11;
  IF (SELECT energy FROM public.characters WHERE id=cid)<cost THEN RAISE EXCEPTION 'Énergie insuffisante : % nécessaires pour terminer cette intervention',cost; END IF;
  UPDATE public.characters SET energy=energy-cost WHERE id=cid;
  UPDATE public.social_stats SET reputation=reputation+rep WHERE character_id=cid;
  UPDATE public.job_mission_runs SET status=CASE WHEN ok THEN 'success' ELSE 'failure' END,reputation_delta=rep,energy_cost=cost WHERE character_id=cid AND game_day=_day;
  IF ok THEN
    ON CONFLICT(character_id,job_key) DO UPDATE SET successes=job_mission_progress.successes+1;
   -- Feed existing career experience, without issuing a salary, bonus or automatic promotion.
   UPDATE public.employments SET progress=progress+1 WHERE character_id=cid AND job_id IN (SELECT id FROM public.jobs WHERE title=s.job_key);
   -- Existing security settlement still owns wages and its own shift outcome; this intervention has no shift reward.
   UPDATE public.security_careers SET missions_ok=missions_ok+1 WHERE character_id=cid AND service=s.job_key AND status='service';
  END IF;
 END IF;
 RETURN public.job_mission_state();
END $$;
REVOKE ALL ON FUNCTION public.job_mission_state(),public.job_mission_choose(date,integer,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.job_mission_state(),public.job_mission_choose(date,integer,integer) TO authenticated,service_role;
COMMIT;
